package com.yeyamo_mobile.api.discovery_service.application;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.discovery_service.application.port.*;import com.yeyamo_mobile.api.discovery_service.domain.model.DiscoveryDocument;
@Service public class DiscoveryProjectionService{private final DiscoverySearchPort search;private final DiscoveryCachePort cache;public DiscoveryProjectionService(DiscoverySearchPort s,DiscoveryCachePort c){search=s;cache=c;}@Transactional public void project(DiscoveryDocument d){search.upsert(d);cache.invalidate();}public Optional<DiscoveryDocument> find(String sourceId){return search.findBySourceId(sourceId);}@Transactional public void interaction(String eventType,String sourceId){double delta=switch(eventType){case"interaction.like.added"->2;case"interaction.like.removed"->-2;case"interaction.favorite.added"->3;case"interaction.favorite.removed"->-3;case"interaction.comment.created"->1.5;case"interaction.comment.deleted"->-1.5;case"interaction.post.shared"->4;case"interaction.checkin.created"->5;default->0;};if(delta!=0){search.adjustTrend(sourceId,delta);cache.invalidate();}}}
